func lengthError(t canopen.DataType, b []byte) error {
	return fmt.Errorf("%w: %s needs %d bytes, got %d", canopen.ErrDataType, t, t.Size(), len(b))
}

func asUint(t canopen.DataType, b []byte, err error) (uint64, error) {
	if err != nil {
		return 0, err
	}
	if len(b) != t.Size() {
		return 0, lengthError(t, b)
	}
	return canopen.DecodeUint(b), nil
}

func asInt(t canopen.DataType, b []byte, err error) (int64, error) {
	if err != nil {
		return 0, err
	}
	if len(b) != t.Size() {
		return 0, lengthError(t, b)
	}
	return canopen.DecodeInt(b), nil
}

func asBool(t canopen.DataType, b []byte, err error) (bool, error) {
	if err != nil {
		return false, err
	}
	if len(b) != t.Size() {
		return false, lengthError(t, b)
	}
	return b[0] != 0, nil
}

func asFloat32(t canopen.DataType, b []byte, err error) (float32, error) {
	if err != nil {
		return 0, err
	}
	if len(b) != t.Size() {
		return 0, lengthError(t, b)
	}
	return math.Float32frombits(uint32(canopen.DecodeUint(b))), nil
}

func asString(t canopen.DataType, b []byte, err error) (string, error) {
	if err != nil {
		return "", err
	}
	v, err := canopen.Decode(t, b)
	if err != nil {
		return "", err
	}
	return v.(string), nil
}

func asBytes(t canopen.DataType, b []byte, err error) ([]byte, error) {
	if err != nil {
		return nil, err
	}
	if n := t.Size(); n != 0 && len(b) != n {
		return nil, lengthError(t, b)
	}
	return b, nil
}
